# Helper envs/base_task.py / BaseTask.safety_metrics_summary
def safety_metrics_summary(self) -> dict:
        """Post-hoc safety metrics (separation stats, intrusion ratios,
        collision rates, approach speed) over the task phase of the
        per-check distance log.  See envs/safety_metrics.py."""
        if self.avatar_collision_checker is None:
            return {"enabled": False}
        records = []
        for r in self.avatar_collision_log:
            if r.get("pretask"):
                continue
            rec = dict(r)
            if "scored_min_distance" in r:
                rec["min_distance"] = r["scored_min_distance"]
                rec["closest_pair"] = r.get("scored_closest_pair")
            records.append(rec)
        out = compute_safety_metrics(
            records,
            thresholds=self._safety_distance_thresholds,
            check_interval_s=self._avatar_collision_stride * self._sim_dt(),
        )
        out["n_pretask_checks_excluded"] = len(self.avatar_collision_log) - len(records)
        out["sim_dt"] = self._sim_dt()
        return out

# envs/task_bases/place_dual_shoes.py / DualShoesTaskCore.check_success
def check_success(self) -> bool:
        """Both shoes must end up within `SUCCESS_DIST_XY_M` (xy) of
        the shoebox centre, at z above the box floor, and resting there
        (``_shoe_resting``)."""
        if not self.plan_success:
            return False
        box_pos = to_numpy(self.shoebox.entity.get_pos()).ravel()[:3]
        box_xy = box_pos[:2]
        # Floor of the box is at table_top (URDF placed at table_top + ε).
        box_floor_z = self.TABLE_TOP_Z + self.SUCCESS_Z_FLOOR_MARGIN_M
        all_in = True
        for i, sh in enumerate(self.shoes):
            p = np.asarray(self._shoe_pos_quat(sh)[0])
            dxy = float(np.linalg.norm(p[:2] - box_xy))
            above_floor = p[2] > box_floor_z
            ok = (dxy <= self.SUCCESS_DIST_XY_M and above_floor
                  and self._shoe_resting(sh, p))
            if not ok:
                all_in = False
        return all_in

