# Helper envs/task_bases/place_dual_shoes.py / DualShoesTaskCore._shoe_resting
def _shoe_resting(self, shoe, pos) -> bool:
        """Success guard for one shoe (see SUCCESS_REST_MAX_ABOVE_RIM_M)."""
        center = np.asarray(pos, dtype=float)
        bottom = float(center[2])
        try:
            aabb = np.asarray(to_numpy(shoe.entity.get_AABB()), dtype=float)
            if aabb.shape == (2, 3) and np.all(np.isfinite(aabb)):
                center = 0.5 * (aabb[0] + aabb[1])
                bottom = float(aabb[0, 2])
        except Exception:
            pass
        rim_z = getattr(self, "_box_rim_z", None)
        if rim_z is not None and bottom > float(rim_z) + self.SUCCESS_REST_MAX_ABOVE_RIM_M:
            return False
        return not held_by_anyone(
            self, shoe, center, radius_m=self.SUCCESS_HELD_TCP_RADIUS_M,
        )

# Helper envs/task_bases/place_dual_shoes.py / DualShoesTaskCore._shoe_pos_quat
def _shoe_pos_quat(shoe):
        """Live base pose, read from the base LINK rather than the entity.

        After the avatar's kinematic attach (which writes entity
        set_pos/set_quat every frame during the inspect) the entity-level
        pos/quat can stay FROZEN at the detach-time values while the body
        physically falls and settles — the entity origin was measured
        20 cm from the collision AABB centre, impossible for this
        rigid body (its mesh origin is ≤4.5 cm from the AABB centre).
        The link state tracks the simulated body."""
        ent = shoe.entity
        links = getattr(ent, "links", None)
        if links:
            link = links[0]
            return (
                to_numpy(link.get_pos()).ravel()[:3],
                to_numpy(link.get_quat()).ravel()[:4],
            )
        return (
            to_numpy(ent.get_pos()).ravel()[:3],
            to_numpy(ent.get_quat()).ravel()[:4],
        )

# Helper envs/base_task.py / BaseTask._compute_target_metrics
def _compute_target_metrics(self) -> Optional[dict]:
        """Resolve the spec into a raw-metrics dict, or None if unavailable.

        Keys: object_pos, target_pos, dist_xy, dist_3d, dz, and (if the spec
        supplies ``object_axis_fn``) tilt_deg = angle(axis, world +Z).
        """
        spec = self.target
        if spec.object is None or spec.position is None:
            return None

        if callable(spec.object_pos_fn):
            try:
                obj_pos = np.asarray(spec.object_pos_fn(),
                                     dtype=float).ravel()[:3]
            except Exception:
                return None
        else:
            entity = getattr(spec.object, "entity", spec.object)
            try:
                obj_pos = np.asarray(to_numpy(entity.get_pos()),
                                     dtype=float).ravel()[:3]
            except Exception:
                return None

        try:
            tgt_raw = spec.position() if callable(spec.position) else spec.position
            tgt_pos = np.asarray(tgt_raw, dtype=float).ravel()[:3]
        except Exception:
            return None

        metrics = {
            "object_pos": obj_pos,
            "target_pos": tgt_pos,
            "dist_xy": float(np.linalg.norm(obj_pos[:2] - tgt_pos[:2])),
            "dist_3d": float(np.linalg.norm(obj_pos - tgt_pos)),
            "dz": float(obj_pos[2] - tgt_pos[2]),
        }

        if callable(spec.object_axis_fn):
            try:
                axis = np.asarray(spec.object_axis_fn(),
                                  dtype=float).ravel()[:3]
                n = float(np.linalg.norm(axis))
                if n > 1e-8:
                    axis = axis / n
                    metrics["tilt_deg"] = float(np.degrees(
                        np.arccos(np.clip(axis[2], -1.0, 1.0))))
            except Exception:
                pass

        return metrics

