# Helper envs/tasks/factory_inspect_pack.py / FactoryInspectPack._item_in_box
def _item_in_box(self, pos: np.ndarray) -> bool:
        bx, by = self.BOX_XY
        ihx, ihy = self.BOX_INNER_HALF
        z0 = self.TABLE_TOP_Z
        return (
            abs(float(pos[0]) - bx) <= ihx
            and abs(float(pos[1]) - by) <= ihy
            and z0 - 0.01 <= float(pos[2]) <= z0 + self.SUCCESS_Z_MAX_ABOVE_TABLE
        )

# Helper envs/manipulation.py / TopDownPickPlaceMixin._get_object_world_center
def _get_object_world_center(self, actor, object_name: str, model_id: int = 0) -> np.ndarray:
        """World-frame geometric centre.  ``actor.get_pose().p`` returns the
        mesh origin which may be offset from the bbox centre — rotate the
        model-space centre into world frame and add.
        """
        model_center = self._get_model_center(object_name, model_id)
        pose = actor.get_pose()
        R = t3d.quaternions.quat2mat(np.array(pose.q))
        return np.array(pose.p) + R @ model_center

